window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c5f72f5484820f0b"]={"versions": [{"id": "FIG-c5f72f5484820f0b", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Komponenten- und Schnittstellendiagramm (statisches Strukturmodell).\n</li><li><strong>Funktionale Einordnung:</strong> Verortet das <code>Operating System Interface</code> (OSI) als funktionalen Cluster der AUTOSAR Adaptive Platform (AP) Foundation und definiert dessen Schnittstellenbeziehung zur <code>Adaptive Application</code> (AA).\n</li><li><strong>Technischer Zweck:</strong> Dokumentiert die architektonische Sonderstellung des OSI-Clusters: Im Gegensatz zu übrigen Functional Clusters (z. B. <code>ara::com</code>, <code>ara::exec</code>), die standardisierte C++-Klassen im <code>ara::*</code>-Namespace definieren, exponiert das OSI native Betriebssystem-Schnittstellen (<code>«aapNativeInterface»</code>), primär ein definiertes POSIX-Subset (PSE51/POSIX.13 mit Erweiterungen) nebst C/C++-Standardbibliotheks-Laufzeit.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Entitäten &amp; Komponenten:</strong>\n<ul class=\"fig-list\"><li><code>Adaptive Application</code>: UML-Komponente (<code>Component</code>), repräsentiert die auf der AP ausgeführte Nutzerapplikation (Instanz eines oder mehrerer POSIX-Prozesse im User Space).\n</li><li><code>«aapFunctionalCluster» Operating System Interface</code>: Plattform-Komponente der AP Foundation; kapselt und standardisiert das zugrundeliegende Host-Betriebssystem (z. B. QNX, Linux/PREEMPT_RT, INTEGRITY, PikeOS).\n</li><li><code>«aapAPI,aapNativeInterface» OperatingSystemInterface</code>: Klassifikator für die Programmierschnittstelle. Die Stereotypenkombination kennzeichnet ein natives, plattformnahes API (POSIX C-APIs, Libc/Libpthread) im Kontrast zu generierten oder objektorientierten <code>ara::</code>-Klassen.\n</li></ul>\n</li><li><strong>Beziehungen &amp; Abhängigkeiten:</strong>\n<ul class=\"fig-list\"><li><code>Adaptive Application</code> $\\xrightarrow{\\text{«use»}}$ <code>OperatingSystemInterface</code>: Nutzungsabhängigkeit (<code>Usage</code>). Die Applikation greift direkt auf die deklarierten OS-Schnittstellen zu.\n</li><li><code>Operating System Interface</code> $\\mathbin{-\\!\\!-\\!\\vartriangle}$ <code>OperatingSystemInterface</code>: Schnittstellenrealisierung (<code>Realization</code>). Der Functional Cluster stellt die definierten OS-Primitiven zur Verfügung.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (falls zutreffend)</h4>\n<ul class=\"fig-list\"><li><strong>Statisches Strukturdiagramm:</strong> Kein zeitlicher Ablauf oder Nachrichtenaustausch explizit modelliert.\n</li><li><strong>Laufzeit-Interaktionsmodell:</strong>\n<ul class=\"fig-list\"><li>Direkte, synchrone Bibliotheks- und Systemaufrufe (Syscalls via Trap in den Kernel-Space bzw. POSIX-Wrapper) aus dem Thread-Kontext der <code>Adaptive Application</code> (z. B. <code>clock_gettime</code>, <code>pthread_mutex_lock</code>).\n</li><li>Keine Vermittlung über IPC-Sockets oder Middleware-Daemons für Basisfunktionen (Threading, Synchronisation, Clocks).\n</li><li>Asynchrone Ereignisse (z. B. POSIX-Timer, Signale) werden betriebssystemseitig direkt an die registrierten Signal-/Event-Handler des Applikationsprozesses zugestellt.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Einschränkung des POSIX-Umfangs:</strong> Entwickler dürfen nicht das unbeschränkte API des Host-Kernels nutzen. Verbindlich ist das spezifizierte AUTOSAR-POSIX-Subset (angelehnt an IEEE 1003.13 PSE51). Nicht konforme Aufrufe (z. B. unkontrolliertes <code>fork()</code>, dynamisches Laden via <code>dlopen()</code> im laufenden Betrieb, unvalidierte IPC-Mechanismen) verletzen die Safety-/Determinismus-Garantien.\n</li><li><strong>Interaktion mit dem Execution Management (EM):</strong> Thread-Erzeugung (<code>pthread_create</code>), Scheduling-Attribute (<code>SCHED_FIFO</code>, <code>SCHED_RR</code>), Prioritäten und CPU-Affinitäten müssen den Restriktionen des <em>Execution Manifests</em> entsprechen; das EM überwacht Budgets und Execution States.\n</li><li><strong>Portabilität &amp; Safety:</strong> Die Abstraktion über <code>«aapNativeInterface»</code> entkoppelt die Applikation von proprietären Kernel-Extensions des Tier-1/SoC-Lieferanten und gewährleistet Portabilität über verschiedene ASIL-zertifizierte Microkernel und RTOS-Implementierungen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-086a7761f3470002", "releases": ["R22-11", "R23-11", "R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Komponenten- und Schnittstellendiagramm (statisches Strukturmodell).\n</li><li><strong>Funktionale Einordnung:</strong> Verortet das <code>Operating System Interface</code> (OSI) als funktionalen Cluster der AUTOSAR Adaptive Platform (AP) Foundation und definiert dessen Schnittstellenbeziehung zur <code>Adaptive Application</code> (AA).\n</li><li><strong>Technischer Zweck:</strong> Dokumentiert die architektonische Sonderstellung des OSI-Clusters: Im Gegensatz zu übrigen Functional Clusters (z. B. <code>ara::com</code>, <code>ara::exec</code>), die standardisierte C++-Klassen im <code>ara::*</code>-Namespace definieren, exponiert das OSI native Betriebssystem-Schnittstellen (<code>«aapNativeInterface»</code>), primär ein definiertes POSIX-Subset (PSE51/POSIX.13 mit Erweiterungen) nebst C/C++-Standardbibliotheks-Laufzeit.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Entitäten &amp; Komponenten:</strong>\n<ul class=\"fig-list\"><li><code>Adaptive Application</code>: UML-Komponente (<code>Component</code>), repräsentiert die auf der AP ausgeführte Nutzerapplikation (Instanz eines oder mehrerer POSIX-Prozesse im User Space).\n</li><li><code>«aapFunctionalCluster» Operating System Interface</code>: Plattform-Komponente der AP Foundation; kapselt und standardisiert das zugrundeliegende Host-Betriebssystem (z. B. QNX, Linux/PREEMPT_RT, INTEGRITY, PikeOS).\n</li><li><code>«aapAPI,aapNativeInterface» OperatingSystemInterface</code>: Klassifikator für die Programmierschnittstelle. Die Stereotypenkombination kennzeichnet ein natives, plattformnahes API (POSIX C-APIs, Libc/Libpthread) im Kontrast zu generierten oder objektorientierten <code>ara::</code>-Klassen.\n</li></ul>\n</li><li><strong>Beziehungen &amp; Abhängigkeiten:</strong>\n<ul class=\"fig-list\"><li><code>Adaptive Application</code> $\\xrightarrow{\\text{«use»}}$ <code>OperatingSystemInterface</code>: Nutzungsabhängigkeit (<code>Usage</code>). Die Applikation greift direkt auf die deklarierten OS-Schnittstellen zu.\n</li><li><code>Operating System Interface</code> $\\mathbin{-\\!\\!-\\!\\vartriangle}$ <code>OperatingSystemInterface</code>: Schnittstellenrealisierung (<code>Realization</code>). Der Functional Cluster stellt die definierten OS-Primitiven zur Verfügung.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Statisches Strukturdiagramm:</strong> Kein zeitlicher Ablauf oder Nachrichtenaustausch explizit modelliert.\n</li><li><strong>Laufzeit-Interaktionsmodell:</strong>\n<ul class=\"fig-list\"><li>Direkte, synchrone Bibliotheks- und Systemaufrufe (Syscalls via Trap in den Kernel-Space bzw. POSIX-Wrapper) aus dem Thread-Kontext der <code>Adaptive Application</code> (z. B. <code>clock_gettime</code>, <code>pthread_mutex_lock</code>).\n</li><li>Keine Vermittlung über IPC-Sockets oder Middleware-Daemons für Basisfunktionen (Threading, Synchronisation, Clocks).\n</li><li>Asynchrone Ereignisse (z. B. POSIX-Timer, Signale) werden betriebssystemseitig direkt an die registrierten Signal-/Event-Handler des Applikationsprozesses zugestellt.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Einschränkung des POSIX-Umfangs:</strong> Entwickler dürfen nicht das unbeschränkte API des Host-Kernels nutzen. Verbindlich ist das spezifizierte AUTOSAR-POSIX-Subset (angelehnt an IEEE 1003.13 PSE51). Nicht konforme Aufrufe (z. B. unkontrolliertes <code>fork()</code>, dynamisches Laden via <code>dlopen()</code> im laufenden Betrieb, unvalidierte IPC-Mechanismen) verletzen die Safety-/Determinismus-Garantien.\n</li><li><strong>Interaktion mit dem Execution Management (EM):</strong> Thread-Erzeugung (<code>pthread_create</code>), Scheduling-Attribute (<code>SCHED_FIFO</code>, <code>SCHED_RR</code>), Prioritäten und CPU-Affinitäten müssen den Restriktionen des <em>Execution Manifests</em> entsprechen; das EM überwacht Budgets und Execution States.\n</li><li><strong>Portabilität &amp; Safety:</strong> Die Abstraktion über <code>«aapNativeInterface»</code> entkoppelt die Applikation von proprietären Kernel-Extensions des Tier-1/SoC-Lieferanten und gewährleistet Portabilität über verschiedene ASIL-zertifizierte Microkernel und RTOS-Implementierungen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-b39355672467ecad", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Komponenten- und Schnittstellendiagramm (statisches Strukturmodell).\n</li><li><strong>Funktionale Einordnung:</strong> Verortet das <code>Operating System Interface</code> (OSI) als funktionalen Cluster der AUTOSAR Adaptive Platform (AP) Foundation und definiert dessen Schnittstellenbeziehung zur <code>Adaptive Application</code> (AA).\n</li><li><strong>Technischer Zweck:</strong> Dokumentiert die architektonische Sonderstellung des OSI-Clusters: Im Gegensatz zu übrigen Functional Clusters (z. B. <code>ara::com</code>, <code>ara::exec</code>), die standardisierte C++-Klassen im <code>ara::*</code>-Namespace definieren, exponiert das OSI native Betriebssystem-Schnittstellen (<code>«aapNativeInterface»</code>), primär ein definiertes POSIX-Subset (PSE51/POSIX.13 mit Erweiterungen) nebst C/C++-Standardbibliotheks-Laufzeit.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Entitäten &amp; Komponenten:</strong>\n<ul class=\"fig-list\"><li><code>Adaptive Application</code>: UML-Komponente (<code>Component</code>), repräsentiert die auf der AP ausgeführte Nutzerapplikation (Instanz eines oder mehrerer POSIX-Prozesse im User Space).\n</li><li><code>«aapFunctionalCluster» Operating System Interface</code>: Plattform-Komponente der AP Foundation; kapselt und standardisiert das zugrundeliegende Host-Betriebssystem (z. B. QNX, Linux/PREEMPT_RT, INTEGRITY, PikeOS).\n</li><li><code>«aapAPI,aapNativeInterface» OperatingSystemInterface</code>: Klassifikator für die Programmierschnittstelle. Die Stereotypenkombination kennzeichnet ein natives, plattformnahes API (POSIX C-APIs, Libc/Libpthread) im Kontrast zu generierten oder objektorientierten <code>ara::</code>-Klassen.\n</li></ul>\n</li><li><strong>Beziehungen &amp; Abhängigkeiten:</strong>\n<ul class=\"fig-list\"><li><code>Adaptive Application</code> $\\xrightarrow{\\text{«use»}}$ <code>OperatingSystemInterface</code>: Nutzungsabhängigkeit (<code>Usage</code>). Die Applikation greift direkt auf die deklarierten OS-Schnittstellen zu.\n</li><li><code>Operating System Interface</code> $\\mathbin{-\\!\\!-\\!\\vartriangle}$ <code>OperatingSystemInterface</code>: Schnittstellenrealisierung (<code>Realization</code>). Der Functional Cluster stellt die definierten OS-Primitiven zur Verfügung.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>Statisches Strukturdiagramm:</strong> Kein zeitlicher Ablauf oder Nachrichtenaustausch explizit modelliert.\n</li><li><strong>Laufzeit-Interaktionsmodell:</strong>\n<ul class=\"fig-list\"><li>Direkte, synchrone Bibliotheks- und Systemaufrufe (Syscalls via Trap in den Kernel-Space bzw. POSIX-Wrapper) aus dem Thread-Kontext der <code>Adaptive Application</code> (z. B. <code>clock_gettime</code>, <code>pthread_mutex_lock</code>).\n</li><li>Keine Vermittlung über IPC-Sockets oder Middleware-Daemons für Basisfunktionen (Threading, Synchronisation, Clocks).\n</li><li>Asynchrone Ereignisse (z. B. POSIX-Timer, Signale) werden betriebssystemseitig direkt an die registrierten Signal-/Event-Handler des Applikationsprozesses zugestellt.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Einschränkung des POSIX-Umfangs:</strong> Entwickler dürfen nicht das unbeschränkte API des Host-Kernels nutzen. Verbindlich ist das spezifizierte AUTOSAR-POSIX-Subset (angelehnt an IEEE 1003.13 PSE51). Nicht konforme Aufrufe (z. B. unkontrolliertes <code>fork()</code>, dynamisches Laden via <code>dlopen()</code> im laufenden Betrieb, unvalidierte IPC-Mechanismen) verletzen die Safety-/Determinismus-Garantien.\n</li><li><strong>Interaktion mit dem Execution Management (EM):</strong> Thread-Erzeugung (<code>pthread_create</code>), Scheduling-Attribute (<code>SCHED_FIFO</code>, <code>SCHED_RR</code>), Prioritäten und CPU-Affinitäten müssen den Restriktionen des <em>Execution Manifests</em> entsprechen; das EM überwacht Budgets und Execution States.\n</li><li><strong>Portabilität &amp; Safety:</strong> Die Abstraktion über <code>«aapNativeInterface»</code> entkoppelt die Applikation von proprietären Kernel-Extensions des Tier-1/SoC-Lieferanten und gewährleistet Portabilität über verschiedene ASIL-zertifizierte Microkernel und RTOS-Implementierungen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-c5f72f5484820f0b", "to": "FIG-086a7761f3470002", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-086a7761f3470002", "to": "FIG-b39355672467ecad", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
